--- a/web/src/pages/status/thresholds.ts
+++ b/web/src/pages/status/thresholds.ts
@@ -1,4 +1,12 @@
 export type Level = "ok" | "warn" | "crit";

+// 백엔드 domain/health.go 의 Classify() 와 같은 값이어야 한다.
+export const WARN_AT = 0.75;
+export const CRIT_AT = 0.90;
+
+export function classify(usage: number): Level {
+  if (usage >= CRIT_AT) return "crit";
+  if (usage >= WARN_AT) return "warn";
+  return "ok";
+}

--- a/web/src/pages/usage/UsageBar.tsx
+++ b/web/src/pages/usage/UsageBar.tsx
@@ -1,8 +1,20 @@
 import "./usage.css";

+/** 0~100 을 10 단위로 접어 폭 클래스를 고른다. */
+function widthClass(pct: number): string {
+  const n = Math.round(Math.max(0, Math.min(100, pct)) / 10) * 10;
+  return `bar-w${n}`;
+}
+
+export function UsageBar({ pct }: { pct: number }) {
+  return (
+    <div className="usage-track">
+      <div className={`usage-fill ${widthClass(pct)}`} />
+    </div>
+  );
+}
