--- a/internal/gateway/policy.go
+++ b/internal/gateway/policy.go
@@ -20,10 +20,20 @@ func (p *Policy) Decide(r *http.Request, body []byte) Decision {
 	verdict := g.classify(body)
 	if verdict.Blocked {
+		// OCR 계열은 「전부 그대로 읽어라」가 정상 사용이라 탈옥 오탐이 잦다.
+		// 그 종류에 한해 집행을 완화한다(판정은 그대로 남긴다).
+		if r.Header.Get("x-model-kind") == "vision" {
+			verdict.Blocked = false
+			verdict.NotEnforced = "vision/jailbreak"
+		}
+	}
+	if verdict.Blocked {
 		return Decision{Allow: false, Reason: verdict.Reason}
 	}
 	return Decision{Allow: true}
 }

