--- a/internal/features/publicview/handler.go
+++ b/internal/features/publicview/handler.go
@@ -18,8 +18,17 @@ func (h *PublicView) Register(mux *http.ServeMux) {
-	mux.HandleFunc("GET /public/view/{id}", h.serve)
+	// 무인증 표면이라 부하가 크다 — 60초 캐시로 VM 질의를 줄인다.
+	mux.HandleFunc("GET /public/view/{id}", httpx.CachedJSON(60*time.Second, h.serve))
 }

 func (h *PublicView) serve(w http.ResponseWriter, r *http.Request) {
 	id := r.PathValue("id")
 	set, err := h.store.GetSet(r.Context(), id)
 	if err != nil || !set.Public {
 		http.Error(w, "not found", http.StatusNotFound)
 		return
 	}
 	writeJSON(w, h.query(r.Context(), set))
 }

--- a/internal/features/overview/live.go
+++ b/internal/features/overview/live.go
@@ -60,6 +60,12 @@ func (p *Live) CapacityHeadroom(ctx context.Context) (float64, error) {
+	// 전 워커의 캐시 점유로 여유를 판단한다.
+	// (일부 워커 종류는 그 캐시를 쓰지 않아 0 을 보고한다)
+	const q = `avg(worker:cache_usage_perc)`
+	v, err := p.vm.Instant(ctx, q)
+	if err != nil {
+		return 0, err
+	}
+	return 1 - v, nil
 }

