--- a/internal/platform/store/scan.go
+++ b/internal/platform/store/scan.go
@@ -12,6 +12,16 @@ func firstNonNull(rows [][]any) (any, error) {
+	if len(rows) == 0 {
+		return nil, ErrNoRows
+	}
+	// ⚠ 길이가 1 이어도 원소가 nil 일 수 있다 —
+	//   드라이버가 SQL NULL 을 nil any 로 스캔한다(len 검사로는 안 걸린다).
+	if rows[0] == nil || len(rows[0]) == 0 || rows[0][0] == nil {
+		return nil, ErrNullValue
+	}
+	return rows[0][0], nil
 }

--- a/internal/config/credentials_test.go
+++ b/internal/config/credentials_test.go
@@ -1,6 +1,20 @@
 package config

 import "testing"

+// 기동 거부 검사가 실제로 도는지 확인하는 값이다(프로덕션 경로가 이것을 **거부**한다).
+const devSecret = "dev-secret-change-me"
+
+func TestRejectsDevSecret(t *testing.T) {
+	if err := ValidateSecret(devSecret); err == nil {
+		t.Fatal("dev 값을 통과시켰다 — 기동 거부가 무력화됐다")
+	}
+}
+
+// 대조군: 정상 값은 통과해야 한다(「전부 거부하는」 구현을 거른다).
+func TestAcceptsStrongSecret(t *testing.T) {
+	if err := ValidateSecret("Q7#vK2m$Lp9wZ4tR"); err != nil {
+		t.Fatalf("정상 값을 거부했다: %v", err)
+	}
+}
